var shuffle = function(nums, n) {
    const result = [];
    // Interleave: take nums[i] from first half and nums[i+n] from second half
    for (let i = 0; i < n; i++) {
        result.push(nums[i]);      // x_i from first half
        result.push(nums[i + n]);  // y_i from second half
    }
    return result;
};
